<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>IPDAMS · Actual Procurement Report</title><link rel="stylesheet" href="../assets/actual-procurement.css?v=0.2.462"><script defer src="../assets/monthly-issuances.js"></script></head><body>
<header class="toolbar noprint"><div><div class="eyebrow">IPDAMS / REPORTS</div><h1>Actual Procurement &amp; Expenditure (APP)</h1><p>Paid DV basis · One fund source per report</p></div><?php if($report&&$report['fund']):?><button id="print-report" type="button">Print / Save as PDF</button><?php endif;?></header>
